import React, { useMemo } from "react";
import { TableHeader, TableRow, TableHead } from "@/components/ui/table";
import { useLanguage } from "@/contexts/LanguageContext";
import { CampaignsType } from "./types";

interface CampaignsTableHeaderProps {
  type: CampaignsType;
  isRTL: boolean;
}

export const CampaignsTableHeader = React.memo(function CampaignsTableHeader({
  type,
  isRTL,
}: CampaignsTableHeaderProps) {
  const { t } = useLanguage();

  const headerCells = useMemo(() => {
    const nameLabel =
      type === "email"
        ? t("marketingEmail.columns.campaignName") || "Campaign Name"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.campaignName") || "Campaign Name"
          : t("marketingNotifications.columns.campaignName") || "Campaign Name";

    const typeLabel =
      type === "notification"
        ? t("marketingNotifications.columns.platform") || "Platform"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.channel") || "Channel"
          : "";

    const audienceLabel =
      type === "email"
        ? t("marketingEmail.columns.audience") || "Audience"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.audience") || "Audience"
          : t("marketingNotifications.columns.audience") || "Audience";

    const sentLabel =
      type === "email"
        ? t("marketingEmail.columns.sent") || "Sent"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.sent") || "Sent"
          : t("marketingNotifications.columns.sent") || "Sent";

    const receivedLabel =
      type === "email"
        ? t("marketingEmail.columns.received") || "Delivered"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.received") || "Received"
          : t("marketingNotifications.columns.received") || "Received";

    const openedLabel =
      type === "email"
        ? t("marketingEmail.columns.opened") || "Opened"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.read") || "Read"
          : t("marketingNotifications.columns.opened") || "Opened";

    const failedLabel =
      type === "email"
        ? t("marketingEmail.columns.failed") || "Failed"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.failed") || "Failed"
          : t("marketingNotifications.columns.failed") || "Failed";

    const dateLabel =
      type === "email"
        ? t("marketingEmail.columns.date") || "Date"
        : type === "sms"
          ? t("marketingWhatsappSms.columns.date") || "Date"
          : t("marketingNotifications.columns.date") || "Date";

    return { nameLabel, typeLabel, audienceLabel, sentLabel, receivedLabel, openedLabel, failedLabel, dateLabel };
  }, [type, t]);

  return (
    <TableHeader>
      <TableRow className="bg-gray-50/80 dark:bg-neutral-800/60 hover:bg-gray-50/80 dark:hover:bg-neutral-800/60 border-b border-gray-200 dark:border-neutral-800">
        <TableHead className={`font-semibold text-gray-500 dark:text-gray-400 px-4 py-3 text-[11px] tracking-wider min-w-[200px] ${isRTL ? "text-right" : "text-left"}`}>
          {headerCells.nameLabel}
        </TableHead>
        {type !== "email" && (
          <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[110px]">
            {headerCells.typeLabel}
          </TableHead>
        )}
        <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[130px]">
          {headerCells.audienceLabel}
        </TableHead>
        <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[90px]">
          {headerCells.sentLabel}
        </TableHead>
        <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[90px]">
          {headerCells.receivedLabel}
        </TableHead>
        <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[90px]">
          {headerCells.openedLabel}
        </TableHead>
        <TableHead className="font-semibold text-red-500 dark:text-red-400 px-3 py-3 text-[11px] tracking-wider text-center w-[90px]">
          {headerCells.failedLabel}
        </TableHead>
        <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[120px] min-w-[110px] whitespace-nowrap">
          {headerCells.dateLabel}
        </TableHead>
        <TableHead className="font-semibold text-gray-500 dark:text-gray-400 px-3 py-3 text-[11px] tracking-wider text-center w-[120px] min-w-[120px] whitespace-nowrap">
          {isRTL ? "العمليات" : "Actions"}
        </TableHead>
      </TableRow>
    </TableHeader>
  );
});
